919	+/** Kiểm đối tượng (từ bộ nhớ đệm) đúng kiểu EnvWeather: cùng phép kiểm số như envParse. */
920	+export function envIsWeather(x: unknown): x is EnvWeather {
921	+  const o: any = x;
922	+  if (!o || typeof o !== 'object') return false;
923	+  const nn = (v: unknown) => v === null || num(v);
924	+  return [o.obs, o.obsMin, o.temp, o.feels, o.hum, o.wind, o.dir, o.rain, o.cloud, o.code].every(num)
925	+    && nn(o.uv) && nn(o.sunrise) && nn(o.sunset) && typeof o.isDay === 'boolean';
926	+}
927	+
928	+/** Mã WMO → khóa i18n + biểu tượng; mã lạ như mã 2 (có mây). */
929	+export function envWx(code: number, isDay: boolean): { key: string; icon: EnvIcon } {
930	+  const dn = isDay ? 'd' : 'n';
931	+  if (code === 0) return { key: isDay ? 'envWxClearD' : 'envWxClearN', icon: ('clear-' + dn) as EnvIcon };
932	+  if (code === 1) return { key: isDay ? 'envWxFewD' : 'envWxFewN', icon: ('cloudy-' + dn) as EnvIcon };
933	+  if (code === 3) return { key: 'envWxOvercast', icon: 'cloud' };
934	+  if (code === 45 || code === 48) return { key: 'envWxFog', icon: 'fog' };
935	+  if (code >= 51 && code <= 57) return { key: 'envWxDrizzle', icon: 'rain' };
936	+  if (code === 61 || code === 66 || code === 80) return { key: 'envWxRainL', icon: 'rain' };
937	+  if (code === 63 || code === 81) return { key: 'envWxRainM', icon: 'rain' };
938	+  if (code === 65 || code === 67 || code === 82) return { key: 'envWxRainH', icon: 'rain' };
939	+  if ((code >= 71 && code <= 77) || code === 85 || code === 86) return { key: 'envWxSnow', icon: 'snow' };
940	+  if (code >= 95 && code <= 99) return { key: 'envWxStorm', icon: 'storm' };
941	+  return { key: 'envWxPartly', icon: ('cloudy-' + dn) as EnvIcon };
942	+}
943	+
944	+const COMPASS = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'] as const;
945	+
946	+/** Hướng gió (độ, hướng gió thổi TỪ đó tới) → 8 hướng; nhận cả số âm / quá 360. */
947	+export function envCompass(deg: number): 'N' | 'NE' | 'E' | 'SE' | 'S' | 'SW' | 'W' | 'NW' {
948	+  const d = ((deg % 360) + 360) % 360;
949	+  return COMPASS[Math.floor((d + 22.5) / 45) % 8];
950	+}
951	+
952	+/** Chỉ số UV → mức; ≤ 0 là '' (không hiện mức). */
953	+export function envUvLevel(uv: number): '' | 'Low' | 'Mod' | 'High' | 'VHigh' | 'Ext' {
954	+  if (!(uv > 0)) return '';
955	+  if (uv < 3) return 'Low';
956	+  if (uv < 6) return 'Mod';
957	+  if (uv < 8) return 'High';
958	+  if (uv < 11) return 'VHigh';
959	+  return 'Ext';
960	+}
